import { useI18n } from "@unimate/i18n/react";
import { useRouter } from "expo-router";
import { useState } from "react";
import { FlatList, Linking, Pressable, View } from "react-native";
import { AppText, Badge, Screen, ScreenHeader, SearchField } from "../../../src/components/ui";
import list from "../../../src/features/legal/third-party.json";

type Entry = { name: string; version: string; license: string; url: string };
const items = list as Entry[];

/** Open-source attribution list (bundled JSON generated by `npm run licenses:build`). */
export default function LicensesScreen() {
  const { t } = useI18n();
  const router = useRouter();
  const [q, setQ] = useState("");
  const needle = q.trim().toLowerCase();
  const shown = needle ? items.filter((i) => `${i.name} ${i.license}`.toLowerCase().includes(needle)) : items;
  return (
    <Screen scroll={false}>
      <ScreenHeader title={t("legal.licenses.title")} onBack={() => router.back()} />
      <SearchField label={t("legal.licenses.search")} value={q} onChangeText={setQ} autoCapitalize="none" autoCorrect={false} />
      <AppText muted variant="caption">{t("legal.licenses.count", { n: shown.length })}</AppText>
      <FlatList
        data={shown}
        keyExtractor={(i) => `${i.name}@${i.version}`}
        initialNumToRender={20}
        renderItem={({ item }) => (
          <Pressable
            accessibilityRole={item.url ? "link" : "text"}
            disabled={!item.url}
            onPress={() => void Linking.openURL(item.url).catch(() => undefined)}
            style={{ paddingVertical: 8, gap: 4, minHeight: 44 }}
          >
            <AppText selectable>{item.name}</AppText>
            <View style={{ flexDirection: "row", flexWrap: "wrap", gap: 8, alignItems: "center" }}>
              <AppText muted variant="caption">{item.version}</AppText>
              <Badge>{item.license || "?"}</Badge>
            </View>
          </Pressable>
        )}
      />
    </Screen>
  );
}
